def use(world: World, actor: Actor, bag: Bag, item_id: str) -> int:
    item = bag.remove(item_id)
    if item.kind == "potion":
        healed = actor.heal(item.power)
        world.events.append(Event("heal", actor.actor_id, amount=healed))
        return healed
    elif item.kind == "shield_tonic":
        actor.shield += item.power
        world.events.append(Event("heal", actor.actor_id, amount=actor.shield))
        return item.power
    else:
        bag.add(item)
        raise ValueError("item is not usable")

def receive(self, amount: int, damage_type: str = "physical") -> int:
    if amount < 0:
        raise ValueError("negative damage")
    if damage_type == "piercing":
        hp_damage = min(self.hp, amount)
        self.hp -= hp_damage
    else:
        shield_damage = min(self.shield, amount)
        self.shield -= shield_damage
        remaining = amount - shield_damage
        hp_damage = 0
        if remaining > 0:
            hp_damage = min(self.hp, remaining)
            self.hp -= hp_damage
    self.alive = self.hp > 0
    return hp_damage

